-- 7didan vector DB + reporting schema dump (plain SQL).
-- Restore with: psql -d <db> -f postgres/7didan_backup.sql
-- or automatically on first `docker compose up` (docker-entrypoint-initdb.d).

CREATE EXTENSION IF NOT EXISTS vector;

DROP TABLE IF EXISTS "7didan_store";
CREATE TABLE "7didan_store" (
    langchain_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    content text,
    embedding vector(1024),
    langchain_metadata json
);

CREATE SCHEMA IF NOT EXISTS reporting;
DROP TABLE IF EXISTS reporting.conversation_events;
CREATE TABLE reporting.conversation_events (
    id bigserial PRIMARY KEY,
    conversation_id text NOT NULL,
    event text NOT NULL CHECK (event IN (
        'started', 'answered', 'abstained', 'qualification_started',
        'qualification_completed', 'abandoned')),
    occurred_at timestamptz NOT NULL DEFAULT now(),
    is_synthetic boolean NOT NULL DEFAULT true
);
CREATE INDEX conversation_events_conv_idx ON reporting.conversation_events (conversation_id);


